/**
 * The form limits and premium features in force for a site.
 *
 * These values come from the site's premium plan and change when the plan changes. Creating or updating a form that
 * exceeds a limit, or that uses a feature absent from `features`, is rejected.
 *
 * Not to be confused with form provider restrictions, which a form schema provider declares once for every site in a
 * namespace it owns, independently of any site's plan. A form must satisfy both.
 */
export interface PremiumRestrictions {
  /**
   * Maximum number of forms allowed on the site.
   *
   * Compare this limit with `totalFormCount`, which counts the same set of forms. Forms in the trash bin aren't
   * counted.
   */
  formsLimit?: Limit;
  /**
   * Maximum number of input fields allowed per form.
   *
   * Display elements, such as rich content and the submit button, don't count toward this limit.
   */
  fieldsLimit?: Limit;
  /** Maximum number of steps allowed per form. */
  stepsLimit?: Limit;
  /**
   * Maximum number of rules allowed per form.
   *
   * Use `rulesLimit` instead. Despite its name, `conditionsLimit` is enforced against the number of rules on a form,
   * not the number of conditions inside them. It's still returned, always with the same value as `rulesLimit`.
   * @deprecated Maximum number of rules allowed per form.
   *
   * Use `rulesLimit` instead. Despite its name, `conditionsLimit` is enforced against the number of rules on a form,
   * not the number of conditions inside them. It's still returned, always with the same value as `rulesLimit`.
   * @replacedBy wix.forms.v4.PremiumRestrictions.rules_limit
   * @targetRemovalDate 2027-03-01
   */
  conditionsLimit?: Limit;
  /** Maximum number of email recipients that can be notified when a form is submitted. */
  emailsLimit?: Limit;
  /**
   * Premium features the site's plan allows.
   *
   * Any feature absent from this list is unavailable on the site, and a form that uses it is rejected.
   * @maxSize 10
   */
  features?: FeatureWithLiterals[];
  /**
   * Ascend by Wix plan the site holds.
   *
   * `NOT_ASCEND` when the site isn't on an Ascend plan. The limits and features that follow from the plan are already
   * reflected in the other fields, so most callers don't need to read this field.
   */
  ascendPlan?: AscendPlanWithLiterals;
  /**
   * Maximum number of rules allowed per form.
   *
   * A single rule's `condition` can combine several tests, and the rule still counts once against this limit.
   */
  rulesLimit?: Limit;
}

/**
 * A single limit the site's plan places on its forms, together with the count at which to warn that the limit is
 * close to being reached.
 */
export interface Limit {
  /**
   * Maximum number allowed.
   *
   * `null` when the plan places no limit.
   * @max 10000
   */
  limit?: number | null;
  /**
   * Count at which to warn that the limit is close to being reached.
   *
   * An absolute count in the same unit as `limit`, never greater than it. Reaching this count doesn't block the
   * action; it's the point at which to surface a nearing-limit warning. For some limits it equals `limit`, meaning
   * there's no early warning.
   *
   * `null` when `limit` is `null`.
   * @max 10000
   */
  warnThreshold?: number | null;
}

export enum Feature {
  /** Unknown feature. */
  UNKNOWN_FEATURE = 'UNKNOWN_FEATURE',
  /** Forms can include a file upload field, letting respondents attach files to their submission. */
  FILE_UPLOAD_FIELD = 'FILE_UPLOAD_FIELD',
  /** Forms can collect payments through payment, fixed payment, and donation fields. */
  ACCEPT_PAYMENTS = 'ACCEPT_PAYMENTS',
  /** Wix branding can be hidden on the published form. */
  REMOVE_WIX_BRANDING = 'REMOVE_WIX_BRANDING',
  /** Forms can include a signature field. */
  SIGNATURE_FIELD = 'SIGNATURE_FIELD',
  /** Files that respondents attached to their submissions can be downloaded from the site's submissions. */
  FILE_DOWNLOAD = 'FILE_DOWNLOAD',
}

/** @enumType */
export type FeatureWithLiterals =
  | Feature
  | 'UNKNOWN_FEATURE'
  | 'FILE_UPLOAD_FIELD'
  | 'ACCEPT_PAYMENTS'
  | 'REMOVE_WIX_BRANDING'
  | 'SIGNATURE_FIELD'
  | 'FILE_DOWNLOAD';

export enum AscendPlan {
  /** Site isn't on an Ascend by Wix plan. */
  NOT_ASCEND = 'NOT_ASCEND',
  /** Ascend by Wix Free plan. */
  FREE = 'FREE',
  /** Ascend by Wix Basic plan. */
  BASIC = 'BASIC',
  /** Ascend by Wix Professional plan. */
  PROFESSIONAL = 'PROFESSIONAL',
  /** Ascend by Wix Unlimited plan. */
  UNLIMITED = 'UNLIMITED',
}

/** @enumType */
export type AscendPlanWithLiterals =
  | AscendPlan
  | 'NOT_ASCEND'
  | 'FREE'
  | 'BASIC'
  | 'PROFESSIONAL'
  | 'UNLIMITED';

export interface GetRestrictionsRequest {
  /**
   * Selects which model the site's limits are resolved from: `true` resolves them from the site's current premium
   * plan, `false` resolves them from Ascend by Wix.
   *
   * Omit the field to let the server decide, which it does by looking up the site's Ascend status and defaulting to
   * the premium-plan model when that lookup is unavailable. External callers always get the server-resolved model.
   * @internal
   */
  killingAscend?: boolean | null;
}

export interface GetRestrictionsResponse {
  /** Form limits and premium features in force for the site. */
  restrictions?: PremiumRestrictions;
  /**
   * Number of forms on the site that count toward `restrictions.formsLimit`.
   *
   * Forms in the trash bin aren't counted. When the count can't be retrieved, the call still succeeds and this field
   * is `0`, so treat `0` as unknown rather than as an empty site before using it to decide whether a form can be
   * added.
   */
  totalFormCount?: number;
}
